#!/usr/bin/env python3
"""Render the source-to-Lean coverage table from its JSON ledger."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / "docs/manuscript-results.json").read_text())
lines = [
    "# Manuscript-to-Lean correspondence", "",
    "Baseline: P1 V1.6, 31 October 2026. This table covers both associated documents.",
    "The JSON ledger records source hashes, source lines, declarations, external inputs",
    "and mathematical-change identifiers. This file is generated by",
    "`python3 scripts/update_alignment.py` from [that ledger](manuscript-results.json).", "",
    "`proved` means the exact aligned statement has a checked Lean proof;",
    "`conditional` means its explicit unformalized inputs remain listed. Neither",
    "a blank declaration field nor a preparatory algebraic lemma establishes coverage.", "",
    "Coverage includes the exact declarations listed below. Preparatory lemmas are",
    "recorded in the project status without counting as complete numbered results.", "",
]
for document, title in (("main", "Main article"), ("companion", "Technical companion")):
    rows = [r for r in data["results"] if r["document"] == document]
    completed = sum(r["status"] == "proved" for r in rows)
    lines += [f"## {title}: {completed} / {len(rows)} proved", "",
              "| Result | Original label and source | Title | Status | Lean declarations |",
              "|---|---|---|---|---|"]
    for r in rows:
        source = f"../manuscripts/paper-p1/v1.6/sources/{r['source']}#L{r['line']}"
        label = f"[{r['label']}]({source})"
        title_text = r["title"].replace("|", "\\|").replace("\n", " ")
        declarations = ", ".join(f"`{d}`" for d in r["lean_declarations"]) or "—"
        lines.append(f"| {r['number']} (p. {r['page']}) | {label} | {title_text} | {r['status']} | {declarations} |")
    lines.append("")
(ROOT / "docs/MANUSCRIPT_ALIGNMENT.md").write_text("\n".join(lines).rstrip() + "\n")
